//! 🧫️ Real admitted payload fixtures retain one original caller stock and all physical receipts.
use semio_framework_job::*;
#[cfg(test)] use semio_framework_job_payload::payload_builder::RetainedPayloadBuilder;
#[cfg(test)] use semio_framework_job_payload::payload_pages_and_ledger::JobPayloadStream;
fn clock()->Option<u64>{Some(1000)}
const STOCK:RetainedCloneGrant=RetainedCloneGrant{maximum_items:4096,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:64};
pub const SOURCE:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:16384,maximum_release_bytes:1048576,maximum_depth:64};
pub fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);assert!(!heap.overflowed);(value,(heap.requested_bytes,heap.released_bytes))}
pub struct OriginalTestPayload{pub caller:OriginalJobFixtureCaller,pub builder:RetainedPayloadBuilder,pub decoder:OriginalJobDecodeOwner,born:usize,released:usize}
impl OriginalTestPayload{
 /// 🎟️ Observes an original owner that already posts its own work and physical receipt.
 pub fn original_turn<R>(&mut self,grant:RetainedCloneGrant,run:impl FnOnce(&mut RetainedPayloadBuilder,&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->Result<R,OriginalTurnFailure>{let(result,heap)=observe(||self.caller.turn_with_decoder(grant,&mut self.decoder,|cx|run(&mut self.builder,cx)));self.record(heap);result}
 pub fn admit(operation:OperationId,generation:Generation,stream:JobPayloadStream,source:&[u8],extent:usize)->Self{Self::prepare(operation,generation,stream,source,extent,false)}
 pub fn admit_single_page(operation:OperationId,generation:Generation,stream:JobPayloadStream,source:&[u8],extent:usize)->Self{assert!(source.len()<=extent);Self::prepare(operation,generation,stream,source,extent,source.is_empty())}
 fn prepare(operation:OperationId,generation:Generation,stream:JobPayloadStream,source:&[u8],extent:usize,reserve_empty:bool)->Self{assert!(extent>0&&extent<=JOB_PAYLOAD_PAGE_BYTES);let(caller,heap)=observe(||OriginalJobFixtureCaller::admit(operation,generation,STOCK,clock,1000000,100000));let mut original=Self{caller,builder:RetainedPayloadBuilder::new(stream),decoder:OriginalJobDecodeOwner::empty(),born:heap.0,released:heap.1};let grant=RetainedCloneGrant{maximum_capacity_bytes:extent,..SOURCE};let mut cursor=0;let empty_source=[0u8];let mut empty_cursor=0;for turn in 0..4096{if original.builder.published().is_some(){break}let(answer,heap)=observe(||original.caller.turn(grant,|cx|{let turn=if !original.builder.is_initialized(){original.builder.advance_initialization(cx)}else if reserve_empty&&original.builder.original().unwrap().page_count()==0{let turn=original.builder.append_original(cx,&empty_source,&mut empty_cursor);assert_eq!(empty_cursor,0);turn}else if cursor<source.len(){original.builder.append_original(cx,source,&mut cursor)}else{original.builder.seal(cx)};receive_original_retained_work(cx,turn)?;Ok(())}));answer.unwrap();original.record(heap);assert!(turn<4095);}assert!(original.builder.published().is_some());assert_eq!(cursor,source.len());original}
 fn record(&mut self,heap:(usize,usize)){let receipt=self.caller.receipt();assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));self.born+=heap.0;self.released+=heap.1;}
 pub fn close(&mut self){for turn in 0..4096{if self.builder.terminal_is_empty(){break}let(answer,heap)=observe(||self.caller.turn(SOURCE,|cx|{let demand=self.builder.retirement_demands()?;close_original_retained_step(cx,demand,|grant|self.builder.close_step_granted(grant))?;Ok(self.builder.terminal_is_empty())}));answer.unwrap();self.record(heap);assert!(turn<4095);}assert!(self.builder.terminal_is_empty());for turn in 0..64{if self.decoder.terminal_is_empty(){break}let(answer,heap)=observe(||self.caller.turn(SOURCE,|cx|{let demand=self.decoder.retirement_demands(cx.retained_grant().maximum_copy_bytes)?;self.decoder.close_on_source(cx)?;Ok(())}));answer.unwrap();self.record(heap);assert!(turn<63);}assert!(self.decoder.terminal_is_empty());for turn in 0..64{if self.caller.terminal_is_empty(){break}let(answer,heap)=observe(||self.caller.retire_step(SOURCE));answer.unwrap();self.record(heap);assert!(turn<63);}assert!(self.caller.terminal_is_empty());let receipt=self.caller.cumulative_receipt();assert_eq!((self.born,self.released),(receipt.retained_capacity_bytes,receipt.released_bytes));assert_eq!(self.born,self.released);}
}
